module alu #(
    parameter ADD = 6'b100000,
    parameter ADDU = 6'b100001,
    parameter SUB = 6'b100010,
    parameter SUBU = 6'b100011,
    parameter AND = 6'b100100,
    parameter OR = 6'b100101,
    parameter XOR = 6'b100110,
    parameter NOR = 6'b100111,
    parameter SLT = 6'b101010,
    parameter SLTU = 6'b101011,
    parameter SLL = 6'b000000,
    parameter SRL = 6'b000010,
    parameter SRA = 6'b000011,
    parameter SLLV = 6'b000100,
    parameter SRLV = 6'b000110,
    parameter SRAV = 6'b000111,
    parameter JR = 6'b001000,
    parameter LUI = 6'b001111
) (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

    wire [31:0] a_signed;
    wire [31:0] b_signed;
    reg [32:0] res;
    reg c;
    reg o;
    assign a_signed = a;
    assign b_signed = b;
    assign r = res[31:0];
    assign zero = (res[31:0] == 0);
    assign negative = res[31];
    assign flag = (aluc == SLT || aluc == SLTU) ? ((aluc == SLT) ? ($signed(a) < $signed(b)) : (a < b)) : 1'b0;
    always @(*) begin
        case(aluc)
            ADD: begin
                res = a + b;
                c = res[32];
                o = (~a[31] & ~b[31] & res[31]) | (a[31] & b[31] & ~res[31]);
            end
            ADDU: begin
                res = a + b;
                c = res[32];
                o = 0;
            end
            SUB: begin
                res = a - b;
                c = res[32];
                o = (a[31] & ~b[31] & ~res[31]) | (~a[31] & b[31] & res[31]);
            end
            SUBU: begin
                res = a - b;
                c = res[32];
                o = 0;
            end
            AND: begin
                res = a & b;
                c = 0;
                o = 0;
            end
            OR: begin
                res = a | b;
                c = 0;
                o = 0;
            end
            XOR: begin
                res = a ^ b;
                c = 0;
                o = 0;
            end
            NOR: begin
                res = ~(a | b);
                c = 0;
                o = 0;
            end
            SLT: begin
                res = ($signed(a) < $signed(b));
                c = 0;
                o = 0;
            end
            SLTU: begin
                res = (a < b);
                c = 0;
                o = 0;
            end
            SLL: begin
                res = b << a;
                c = 0;
                o = 0;
            end
            SRL: begin
                res = b >> a;
                c = 0;
                o = 0;
            end
            SRA: begin
                res = $signed(b) >>> a;
                c = 0;
                o = 0;
            end
            SLLV: begin
                res = b << a[4:0];
                c = 0;
                o = 0;
            end
            SRLV: begin
                res = b >> a[4:0];
                c = 0;
                o = 0;
            end
            SRAV: begin
                res = $signed(b) >>> a[4:0];
                c = 0;
                o = 0;
            end
            LUI: begin
                res = {a[15:0], 16'b0};
                c = 0;
                o = 0;
            end
            default: begin
                res = 33'b0;
                c = 0;
                o = 0;
            end
        endcase
    end
endmodule
